export const BODY: string = "\n<p>ایک تصویر کمپریس کرنے میں ایک منٹ لگتا ہے۔ پچاس تصویریں دوپہر لے لیتی ہیں، جب تک آپ انہیں بیچ میں نہ کریں۔</p>\n<p>بیچ کمپریشن پورا فولڈر ایک ساتھ پروسیس کرتا ہے۔ آپ پیش سیٹ چنتے ہیں، پیش رفت بار دیکھتے ہیں اور سب کچھ ZIP کے طور پر ایک ساتھ ڈاؤن لوڈ کرتے ہیں۔</p>\n<p>یہ رہنما پورا ورک فلو بتاتا ہے، فائلیں جمع کرنے سے لے کر تیار ZIP جانچنے تک۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے کیا چاہیے</h2>\n<p>اصل تصویریں ایک فولڈر میں جمع کریں۔ اصل سے کام کرنے سے بہترین کوالٹی ملتی ہے، کمپریس شدہ کاپیوں سے کام کرنے سے نقصان بڑھتا ہے۔</p>\n<p>طے کریں کہ تصویریں کس لیے ہیں۔ تھمب نیل کو Smaller File پیش سیٹ چاہیے، جبکہ پورٹ فولیو شاٹ کو High Quality چاہیے۔</p>\n<p>جانچیں کہ آپ کے پاس کتنی تصویریں ہیں۔ بیس کا بیچ کہیں بھی جلد چلتا ہے، جبکہ دو سو کا بیچ فون پر تقسیم کرنے کی ضرورت پڑ سکتی ہے۔</p>\n<h2 id=\"step-1-open\">مرحلہ 1: بلک کمپریسر کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/bulk-tasveer-compress-karein/\">Bulk Image Compressor</a> کھولیں۔ اکاؤنٹ یا انسٹال کی ضرورت نہیں ہے۔</p>\n<p>ٹول مکمل طور پر آپ کے آلے پر چلتا ہے۔ آپ کی تصویریں مقامی طور پر پروسیس ہوتی ہیں اور کبھی کسی سرور پر اپ لوڈ نہیں ہوتیں۔</p>\n<p>اگر آپ لیپ ٹاپ پر ہیں تو صفحہ ڈریگ اینڈ ڈراپ کے ساتھ بہترین کام کرتا ہے۔ فون پر اپ لوڈ بٹن آپ کی گیلری کھولتا ہے۔</p>\n<h2 id=\"step-2-add-files\">مرحلہ 2: اپنی تصویریں شامل کریں</h2>\n<p>اپنی تصویریں اپ لوڈ والے حصے پر گھسیٹ دیں، یا براؤز کرنے کے لیے ٹیپ کریں اور انہیں چنیں۔ زیادہ تر براؤزر پر آپ پورا فولڈر ایک ساتھ شامل کر سکتے ہیں۔</p>\n<p>JPG، PNG، WebP اور HEIC فائلیں قبول ہوتی ہیں۔ ملے جلے بیچ ٹھیک کام کرتے ہیں، اس لیے تصویریں اور اسکرین شاٹ ایک بیچ میں رہ سکتے ہیں۔</p>\n<p>فائلیں شامل کرنے کے بعد قطار جانچیں۔ ہر تصویر اپنے نام اور سائز کے ساتھ دکھائی دینی چاہیے، اس لیے گم شدہ فائل آسانی سے نظر آ جاتی ہے۔</p>\n<h2 id=\"step-3-preset\">مرحلہ 3: پیش سیٹ چنیں</h2>\n<p>زیادہ تر کام کے لیے Balanced چنیں۔ یہ 70 فیصد کوالٹی سے شروع ہوتا ہے اور سائز اور شکل کے درمیان اچھا درمیانی راستہ دیتا ہے۔</p>\n<p>تھمب نیل، اوتار اور چھوٹی دکھائی دینے والی تصویروں کے لیے Smaller File چنیں۔ چھوٹے سائز پر اضافی کمپریشن نظر نہیں آتی۔</p>\n<p>پورٹ فولیو، گیلری اور نمائشی تصویروں کے لیے High Quality چنیں۔ فائلیں بڑی رہتی ہیں، مگر تفصیل اس کے قابل ہوتی ہے۔</p>\n<h2 id=\"step-4-run\">مرحلہ 4: بیچ چلائیں</h2>\n<p>بیچ شروع کریں اور پیش رفت بار دیکھیں۔ یہ دکھاتا ہے کہ کون سی فائلیں مکمل ہوئیں اور اب تک کتنا کل سائز بچا ہے۔</p>\n<p>پروسیسنگ ایک وقت میں ایک تصویر ہوتی ہے۔ اس سے براؤزر کام کرتے ہوئے جمے بغیر جوابدہ رہتا ہے۔</p>\n<p>بیچ چلتے ہوئے ٹیب بند نہ کریں۔ کام آپ کے براؤزر میں ہوتا ہے، اس لیے صفحہ بند کرنے سے کمپریشن رک جاتی ہے۔</p>\n<h2 id=\"step-5-preview\">مرحلہ 5: انفرادی نتائج کا پیش نظارہ دیکھیں</h2>\n<p>بیچ مکمل ہونے پر ڈاؤن لوڈ سے پہلے نتائج کا پیش نظارہ دیکھیں۔ کسی بھی تصویر پر کلک کریں تو وہ مکمل سائز میں دکھائی دیتی ہے۔</p>\n<p>پہلے مشکل ترین تصویریں جانچیں۔ تفصیلی تصویر یا چھوٹے متن والا اسکرین شاٹ سادہ پورٹریٹ سے پہلے مسائل دکھائے گا۔</p>\n<p>چند نتائج کا اصل سے موازنہ کریں۔ چھوٹے فرق معمول ہیں، ناقابل پڑھ متن یا دھبے والی جلد نہیں۔</p>\n<h2 id=\"step-6-download-zip\">مرحلہ 6: ZIP ڈاؤن لوڈ کریں</h2>\n<p>Download All پر کلک کر کے ایک ZIP فائل لیں جس میں ہر کمپریس شدہ تصویر ہو۔ ZIP سیٹ کو ایک پیکج میں منظم رکھتا ہے۔</p>\n<p>ZIP کو اپنے فولڈر میں نکالیں۔ اس سے کمپریس شدہ سیٹ اصل سے الگ اور بعد میں آسانی سے ملنے والا رہتا ہے۔</p>\n<p>نکالی گئی فائلیں جانچیں۔ چند کو مکمل سائز میں کھولیں اور کہیں اپ لوڈ کرنے سے پہلے یقین کریں کہ وہ درست لگتی ہیں۔</p>\n<h2 id=\"fixing-problems\">بیچ میں مسائل ٹھیک کرنا</h2>\n<p>اگر کوئی تصویر بڑی ہو گئی تو اسے ویسے ہی چھوڑ دیں۔ ٹول خبردار کرتا ہے جب دوبارہ انکوڈ کرنے سے فائل بڑی ہو جائے، اور اصل بہتر فائل ہوتی ہے۔</p>\n<p>اگر تصویر دھندلی لگے تو ماخذ بہت چھوٹا ہو سکتا ہے۔ اس ایک فائل کو بڑے اصل سے High Quality پیش سیٹ کے ساتھ دوبارہ کمپریس کریں۔</p>\n<p>اگر رنگ غلط لگیں تو شفافیت جانچیں۔ شفاف PNG کو JPG میں بدلنے سے پس منظر بھر جاتا ہے، عام طور پر سفید سے۔</p>\n<h2 id=\"blog-workflow\">ورک فلو: بلاگ تھمب نیل کا سیٹ</h2>\n<p>کئی پوسٹوں کے تھمب نیل جمع کریں اور انہیں ایک بیچ کے طور پر اپ لوڈ کریں۔ مستقل نتائج کے لیے Balanced پیش سیٹ چنیں۔</p>\n<p>تین یا چار نتائج کا پیش نظارہ دیکھیں، صرف پہلا نہیں۔ اچھے نتائج میں ایک خراب تھمب نیل چھپ سکتا ہے۔</p>\n<p>ZIP ڈاؤن لوڈ کریں، نکالیں اور فائلیں اپنے بلاگ پر اپ لوڈ کریں۔ اصل رکھیں، اگر کسی پوسٹ کو بعد میں بڑی تصویر چاہیے ہو۔</p>\n<h2 id=\"shop-workflow\">ورک فلو: مصنوعات کا کیٹلاگ</h2>\n<p>لانچ کے لیے مصنوعات کے شاٹ جمع کریں اور انہیں ایک بیچ کے طور پر اپ لوڈ کریں۔ High Quality پیش سیٹ استعمال کریں تاکہ مصنوعات بہترین لگیں۔</p>\n<p>سب سے تفصیلی مصنوعات پہلے پیش نظارہ دیکھیں۔ کپڑے کی بناوٹ اور چھپے لیبل سب سے پہلے نرم ہوتے ہیں۔</p>\n<p>ZIP ڈاؤن لوڈ کریں اور تصویریں دکان پر اپ لوڈ کریں۔ چند مصنوعات کے صفحے جانچ کر یقین کریں کہ تصویریں درست دکھائی دیتی ہیں۔</p>\n<h2 id=\"album-workflow\">ورک فلو: شیئر شدہ فوٹو البم</h2>\n<p>البم کی تصویریں جمع کریں اور انہیں ایک بیچ کے طور پر اپ لوڈ کریں۔ Balanced پیش سیٹ البم کو یادوں کو نقصان پہنچائے بغیر ہلکا رکھتا ہے۔</p>\n<p>ڈاؤن لوڈ سے پہلے چند پسندیدہ تصویروں کا پیش نظارہ دیکھیں۔ سو کے بیچ میں بھی پیاری تصویر احتیاط سے جانچنے کی مستحق ہے۔</p>\n<p>ZIP ڈاؤن لوڈ کریں اور خاندان یا دوستوں کے ساتھ شیئر کریں۔ کمپریس شدہ البم سست کنکشن پر بھی جلد ڈاؤن لوڈ ہوتا ہے۔</p>\n<h2 id=\"folder-selection\">پورا فولڈر ایک ساتھ چننا</h2>\n<p>زیادہ تر ڈیسک ٹاپ براؤزر آپ کو انفرادی فائلوں کی بجائے پورا فولڈر چننے دیتے ہیں۔ یہ بیچ شروع کرنے کا تیز ترین طریقہ ہے۔</p>\n<p>فائل پکر میں فولڈر والا انتخاب تلاش کریں۔ یہ ڈیسک ٹاپ پر کروم، ایج اور فائر فاکس میں الگ انتخاب کے طور پر دکھائی دیتا ہے۔</p>\n<p>فولڈر چننے کے بعد قطار جانچیں۔ براؤزر کے حساب سے ذیلی فولڈر شامل یا نظر انداز ہو سکتے ہیں، اس لیے گنتی میل کھانا یقینی کریں۔</p>\n<h2 id=\"progress-bar\">پیش رفت بار پڑھنا</h2>\n<p>پیش رفت بار بتاتا ہے کہ بیچ کہاں تک پہنچا ہے اور اب تک کتنا سائز بچا ہے۔ ہر تصویر مکمل ہونے پر یہ اپ ڈیٹ ہوتا ہے۔</p>\n<p>مستقل رفتار کا مطلب ہے کہ بیچ صحت مند ہے۔ اگر بار ایک فائل پر رک جائے تو وہ فائل غیر معمولی بڑی یا پیچیدہ ہو سکتی ہے۔</p>\n<p>بار چلتے ہوئے ٹیب بند نہ کریں۔ کام آپ کے براؤزر میں ہوتا ہے، اور صفحہ بند کرنے سے بیچ رک جاتا ہے۔</p>\n<h2 id=\"per-file-results\">فی فائل نتائج سمجھنا</h2>\n<p>ہر مکمل فائل اپنا نتیجہ دکھاتی ہے: اصل سائز، کمپریس شدہ سائز اور بچت کا فیصد۔ بیچ میں عدد بہت مختلف ہوتے ہیں۔</p>\n<p>سادہ پورٹریٹ اکثر نوے فیصد یا زیادہ بچاتے ہیں۔ تفصیلی مناظر صرف ستر فیصد بچا سکتے ہیں، کیونکہ ان میں رکھنے والا ڈیٹا زیادہ ہوتا ہے۔</p>\n<p>جس فائل نے تقریباً کچھ نہیں بچایا، وہ شاید پہلے سے کمپریس تھی۔ ٹول نے اپنی بہترین کوشش کی، مگر ہٹانے کو کچھ باقی نہیں تھا۔</p>\n<h2 id=\"retrying-failed\">ناکام یا خراب فائلیں دوبارہ آزمانا</h2>\n<p>بیچ میں کچھ فائلیں ناکام ہوتی ہیں یا خراب نکلتی ہیں۔ یہ معمول ہے، اور حل انہیں الگ سے سنبھالنا ہے۔</p>\n<p>مسئلہ والی فائل سیٹ سے نکالیں۔ اسے اکیلے High Quality پیش سیٹ کے ساتھ کمپریس کریں اور نتیجہ احتیاط سے پیش نظارہ دیکھیں۔</p>\n<p>اگر فارمیٹ مسئلہ ہو تو اسے بدلیں۔ JPG کے طور پر دوبارہ کمپریس شدہ PNG تصویر اکثر ناکامی سے صاف نتیجے میں بدل جاتی ہے۔</p>\n<h2 id=\"uploading-after-batch\">بیچ نتائج اپ لوڈ کرنا</h2>\n<p>نکالنے کے بعد فائلیں اپنی منزل پر گروپوں میں اپ لوڈ کریں۔ پچاس فائلیں ایک ساتھ اپ لوڈ کرنا کچھ پلیٹفارم کو پریشان کر سکتا ہے۔</p>\n<p>پہلی چند اپ لوڈ احتیاط سے جانچیں۔ باقی سیٹ اپ لوڈ کرنے سے پہلے یقین کریں کہ وہ درست دکھائی دیتی ہیں۔</p>\n<p>فائل ناموں کو ان کی منزلوں سے ملائیں۔ غلط مصنوعات کے صفحے پر اپ لوڈ شدہ مصنوعات کی تصویر شرمناک اور قابل بچاؤ غلطی ہے۔</p>\n<h2 id=\"time-estimates\">بیچ میں کتنا وقت لگتا ہے؟</h2>\n<p>جدید لیپ ٹاپ پر بیس فون تصویروں کا بیچ تقریباً ایک منٹ لیتا ہے۔ وہی بیچ فون پر تین منٹ لے سکتا ہے۔</p>\n<p>بڑی فائلیں زیادہ وقت لیتی ہیں۔ 10 MB کیمرہ تصویروں کے بیچ کو فی فائل 2 MB فون شاٹ کے بیچ سے زیادہ پروسیسنگ وقت چاہیے ہوتا ہے۔</p>\n<p>پیش سیٹ رفتار پر بھی اثر ڈالتا ہے۔ High Quality Smaller File سے زیادہ اصلاح کے مراحل چلاتا ہے، اس لیے تھوڑا زیادہ وقت لیتا ہے۔</p>\n<h2 id=\"sharing-zip\">دوسروں کے ساتھ ZIP شیئر کرنا</h2>\n<p>ZIP فائل کمپریس شدہ سیٹ شیئر کرنے کا آسان ترین طریقہ ہے۔ ایک فائل ہر تصویر رکھتی ہے، نکالنے اور استعمال کے لیے تیار۔</p>\n<p>جب کافی چھوٹی ہو تو ZIP ای میل سے بھیجیں۔ زیادہ تر ای میل نظام 20 MB یا 25 MB تک منسلکات قبول کرتے ہیں۔</p>\n<p>بڑے ZIP کے لیے فائل شیئرنگ لنک استعمال کریں۔ ZIP ڈرائیو پر اپ لوڈ کریں اور فائل کی بجائے لنک شیئر کریں۔</p>\n<h2 id=\"cleanup-after\">بیچ کے بعد صفائی</h2>\n<p>بیچ اپ لوڈ اور تصدیق ہونے کے بعد کام کی فائلیں صاف کریں۔ صاف ورک اسپیس اگلے بیچ میں الجھن روکتی ہے۔</p>\n<p>نکالی گئی کمپریس شدہ کاپیاں محفوظ اپ لوڈ ہونے کے بعد حذف کر دیں۔ ZIP سیٹ کی بیک اپ کے طور پر رہتا ہے۔</p>\n<p>اصل ہمیشہ رکھیں۔ وہ اپنے فولڈر میں رہتے ہیں، ہر کمپریس شدہ کاپی سے الگ۔</p>\n<h2 id=\"final-check\">اپ لوڈ سے پہلے آخری جانچ</h2>\n<p>تیار بیچ سے تین بے ترتیب تصویریں مکمل سائز میں کھولیں۔ اگر وہ صاف لگیں تو بیچ اچھا ہے، اگر ایک نرم لگے تو اپ لوڈ سے پہلے باقی جانچیں۔</p>\n<p>یقین کریں کہ ZIP درست نکلا ہے اور فائل گنتی اصل بیچ سے میل کھاتی ہے۔ اب گم شدہ فائل لائیو صفحے پر گم شدہ تصویر سے آسان ٹھیک ہوتی ہے۔</p>\n<p>بلک کمپریشن کی مکمل رہنما <a href=\"/ur/blog/bulk-tasveer-compressor-rehnumai/\">Bulk Image Compressor: Complete Guide</a> میں پڑھیں۔ بیچ کی بہترین عادات کے لیے <a href=\"/ur/blog/batch-tasveer-compression-behtareen-tareeqe/\">Batch Compression: ZIP Workflow and Best Practices</a> دیکھیں۔ اگر آپ کو بالکل فائل سائز چاہییں تو <a href=\"/ur/makhsus-size-tak-tasveer-compress-karein/\">Target File Size Compressor</a> آپ کا لکھا کوئی بھی عدد لیتا ہے۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"تصویروں کا پورا فولڈر ایک ساتھ کیسے کمپریس کروں؟","answer":"بلک کمپریسر کھولیں اور فولڈر کو اپ لوڈ والے حصے پر گھسیٹ دیں، یا تمام فائلیں ایک ساتھ چنیں۔ پیش سیٹ چنیں، بیچ چلائیں اور نتائج ایک ZIP کے طور پر ڈاؤن لوڈ کریں۔ ہر تصویر بہترین کوالٹی کے لیے الگ الگ کمپریس ہوتی ہے۔"},{"question":"بلاگ تھمب نیل کے لیے کون سا پیش سیٹ استعمال کروں؟","answer":"زیادہ تر تھمب نیل کے لیے Balanced اچھا کام کرتا ہے، 70 فیصد کوالٹی سے شروع ہوتا ہے۔ اگر تھمب نیل بہت چھوٹے دکھائے جاتے ہیں تو Smaller File استعمال کریں، اور اگر وہ بڑی نمایاں تصویریں ہیں تو High Quality استعمال کریں۔ پورا بیچ ڈاؤن لوڈ کرنے سے پہلے چند نتائج پیش نظارہ دیکھیں۔"},{"question":"کیا فون پر بڑی تعداد میں تصویریں کمپریس کر سکتا ہوں؟","answer":"جی ہاں، ٹول موبائل براؤزر میں کام کرتا ہے۔ فون پر بیچ چھوٹے رکھیں، ایک وقت میں تقریباً بیس تصویریں، کیونکہ فون میں میموری کم ہوتی ہے۔ ZIP کو اپنی Files ایپ میں ڈاؤن لوڈ کریں اور وہیں نکالیں۔"},{"question":"اگر بیچ کے دوران فون کی میموری ختم ہو جائے تو کیا ہوتا ہے؟","answer":"بیچ سست ہو سکتا ہے یا رک سکتا ہے۔ باقی تصویروں کو چھوٹے گروپ میں تقسیم کریں اور انہیں الگ سے چلائیں۔ ڈیسک ٹاپ براؤزر بڑے بیچ آرام سے سنبھالتے ہیں، اس لیے بہت بڑے کام کے لیے لیپ ٹاپ استعمال کریں۔"},{"question":"کیا بلک کمپریشن سے پہلے تصویریں ری سائز کرنی چاہییں؟","answer":"نہیں، بلک کمپریسر اصل پکسل ابعاد رکھتا ہے اور صرف فائل سائز کم کرتا ہے۔ اگر آپ کو چھوٹے ابعاد بھی چاہییں تو پہلے تصویریں امیج ری سائزر سے ری سائز کریں، پھر ری سائز شدہ فائلیں بیچ میں کمپریس کریں۔"},{"question":"کیسے جانوں کہ بیچ نے واقعی جگہ بچائی؟","answer":"بیچ خلاصہ کمپریشن سے پہلے اور بعد کا کل سائز بتاتا ہے، ساتھ بچت کا فیصد بھی۔ عام فوٹو بیچ اسی سے نوے فیصد کم ہو جاتا ہے۔ آپ ZIP سائز کا اصل فولڈر سائز سے موازنہ بھی کر سکتے ہیں۔"}];
